import html,json,shutil
from pathlib import Path
B=Path(__file__).resolve().parent; O=B.parents[1]/'outputs';O.mkdir(exist_ok=True)
data=json.loads((B/'overlap-summary.json').read_text());N=data['atlas_complexes'];Q=data['atlas_unique_chains']
screen=json.loads((B/'screening-summary.json').read_text());cohort=json.loads((B/'atlas-cohort-stats.json').read_text())
progress=json.loads((B/('verification.json' if (B/'verification.json').exists() else 'download-progress.json')).read_text())
qc=progress.get('source_qc_exclusions',[])
qc_note=('One recovered file (<code>ID_464531</code>) has matching sequences but mean CA pLDDT 49.53 versus metadata 50.34. It is retained as a source file and flagged for exclusion from preparation pending review.' if qc else '')
rows={(r['dataset'],str(r['identity'])):r for r in data['rows']}
names={
 'PINDER_train':'PINDER training','pKPDB_train':'pKPDB training (including monomers)',
 'pKPDB_complex_train':'pKPDB complex training','benchmark_train':'Frozen benchmark training split',
 'PINDER_val':'PINDER validation','pKPDB_val':'pKPDB validation (including monomers)',
 'pKPDB_complex_val':'pKPDB complex validation','benchmark_active_val142':'Active benchmark validation',
 'benchmark_val':'Full benchmark validation split','benchmark_test':'Benchmark test split',
 'benchmark_reserved':'Reserved benchmark subset','heldout_all':'Frozen held-out chains, grouped by complex',
 'reference_experimental':'Experimental reference chains','PINDER_accepted':'All accepted PINDER',
 'pKPDB_accepted_source_entities':'All accepted pKPDB: source entities',
 'benchmark_all':'Full benchmark universe','PINDER_retired_val400':'Retired PINDER validation (400)',
 'current_training_union':'Current PINDER + pKPDB training union',
 'current_complex_training_union':'Current complex training union (monomers excluded)',
 'all_training_union':'Current pools + frozen benchmark training split',
 'current_validation_union':'Current validation union (800 + 800 + 142)',
 'all_validation_and_test_union':'Current validation + full benchmark validation/test',
 'reference_benchmark':'Benchmark reference sequences'}
def count(n):return f'{n:,}'
def percent(n,d):return f'{n/d:.2%}' if 0<n/d<.001 else f'{n/d:.1%}'
def cell(n,d=None):return count(n)+(f' <span class="muted">({percent(n,d)})</span>' if d else '')
def table(datasets,threshold='0.7'):
 result='<div class="scroll"><table><thead><tr><th>Reference dataset</th><th>Entries</th><th>ATLAS complexes: any chain</th><th>ATLAS complexes: both chains somewhere</th><th>ATLAS complexes: both in one entry</th><th>Reference unique chains covered by ATLAS</th></tr></thead><tbody>'
 for name in datasets:
  r=rows[name,threshold];p=r['atlas_complexes_same_reference_complex']
  result+=f'<tr><th>{names[name]}</th><td>{count(r["reference_records"])}</td><td>{cell(r["atlas_complexes_any_chain"],N)}</td><td>{cell(r["atlas_complexes_both_chains"],N)}</td><td>{cell(p,N) if p is not None else "—"}</td><td>{count(r["reference_chains_covered"])} / {cell(r["reference_unique_chains"])} <span class="muted">({percent(r["reference_chains_covered"],r["reference_unique_chains"])})</span></td></tr>'
 return result+'</tbody></table></div>'
training=['PINDER_train','pKPDB_complex_train','pKPDB_train','current_complex_training_union','current_training_union','benchmark_train','all_training_union']
validation=['PINDER_val','pKPDB_complex_val','pKPDB_val','benchmark_active_val142','current_validation_union','benchmark_val','benchmark_test','all_validation_and_test_union','benchmark_reserved','heldout_all']
scope=['PINDER_accepted','pKPDB_accepted_source_entities','benchmark_all','PINDER_retired_val400','reference_experimental']
threshold_table='<div class="scroll"><table><thead><tr><th>Identity</th><th>Current training: any chain</th><th>Current validation: any chain</th><th>Validation + test: any chain</th><th>ATLAS unique chains matching current training</th></tr></thead><tbody>'
for t in ['exact','0.95','0.9','0.7','0.5','0.3']:
 tr=rows['current_training_union',t]
 threshold_table+='<tr><th>'+('Exact full sequence' if t=='exact' else f'≥{float(t):.0%}')+'</th>'+''.join('<td>'+cell(rows[d,t]['atlas_complexes_any_chain'],N)+'</td>' for d in ['current_training_union','current_validation_union','all_validation_and_test_union'])+'<td>'+cell(tr['atlas_unique_chains_matched'],Q)+'</td></tr>'
threshold_table+='</tbody></table></div>'
status=(f'Complete: {count(progress["downloaded_unique"])} / {count(N)} structures retained; all retained shard checksums verified.' if progress['complete'] else f'In progress: {count(progress["downloaded_unique"])} / {count(N)} structures retained; {progress["verified_archive_receipts"]} / {progress["expected_archives"]} archive receipts.')
body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ATLAS × jax-Ka — sequence coverage</title>
<style>:root{{color-scheme:light;--ink:#172d3b;--muted:#506574;--line:#dbe4e7;--accent:#136b65}}*{{box-sizing:border-box}}body{{margin:0;background:#f3f6f5;color:var(--ink);font:16px/1.6 system-ui,-apple-system,sans-serif}}main{{max-width:1400px;margin:auto;padding:48px 36px}}header{{border-top:5px solid var(--accent);padding-top:24px}}h1{{font-size:clamp(30px,4vw,48px);line-height:1.15;letter-spacing:-1.5px;margin:10px 0 16px}}h2{{font-size:25px;margin:36px 0 12px}}h3{{font-size:19px}}p{{max-width:1000px}}a{{color:#12615f}}.eyebrow{{text-transform:uppercase;letter-spacing:2px;font-size:12px;color:var(--muted)}}.lead{{font-size:20px}}.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:28px 0}}.card{{background:white;padding:22px;border:1px solid var(--line);border-radius:10px}}.card strong{{font-size:30px;display:block;line-height:1.3}}.card span,.muted{{color:var(--muted);font-size:13px}}.note{{background:#e6f0ed;border-left:4px solid var(--accent);padding:16px 22px;margin:22px 0}}.scroll{{overflow-x:auto;background:white;border:1px solid var(--line);border-radius:8px}}table{{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5}}th,td{{padding:12px 14px;border-bottom:1px solid var(--line);text-align:right;vertical-align:top}}th:first-child{{text-align:left;min-width:230px}}thead th{{background:#e7eeed;font-size:12px;font-weight:650;text-align:right}}tbody th{{font-weight:500}}tr:last-child td,tr:last-child th{{border-bottom:0}}td{{font-variant-numeric:tabular-nums;white-space:nowrap}}code{{background:#e5ecec;padding:2px 5px;border-radius:3px;font-size:13px;overflow-wrap:anywhere}}li{{margin:9px 0}}footer{{margin-top:40px;border-top:1px solid var(--line);padding-top:20px;color:var(--muted);font-size:13px}}@media(max-width:750px){{main{{padding:25px 16px}}.cards{{grid-template-columns:repeat(2,1fr)}}.card{{padding:16px}}.card strong{{font-size:25px}}}}</style></head><body><main>
<header><div class="eyebrow">jax-Ka · Frozen audit · 10 October 2026</div><h1>ATLAS complex sequence coverage</h1><p class="lead">A complete sequence audit of the 181,671 high-confidence ATLAS complexes against the current training pools, validation sets, and frozen benchmark references.</p></header>
<div class="cards"><div class="card"><strong>{count(N)}</strong><span>high-confidence complexes</span></div><div class="card"><strong>{count(Q)}</strong><span>unique full chain sequences</span></div><div class="card"><strong>{percent(rows['current_training_union','0.7']['atlas_complexes_any_chain'],N)}</strong><span>share a ≥70%-identity chain with current training</span></div><div class="card"><strong>{count(screen['current_validation_any_chain_70'])}</strong><span>overlap current validation at ≥70% identity</span></div></div>
<div class="note"><strong>Structure download:</strong> {status}<br><span class="muted">Snapshot {html.escape(progress['timestamp_utc'])}. Retained data: {progress['retained_bytes']/1e9:.2f} GB. Downloaded structures remain separate from active training.</span></div>
{('<p><strong>Source-quality exception:</strong> '+qc_note+'</p>') if qc_note else ''}
<p><strong>Reading the tables:</strong> the default is ≥70% aligned sequence identity and ≥80% coverage of <em>each</em> chain. “Any chain” flags an ATLAS complex if either partner matches. “Both chains somewhere” allows matches in different reference entries. “Both in one entry” requires two distinct chain occurrences within one reference entry, permitting swapped partners and homomer copies. It does not establish an identical interface or the same complete assembly.</p>
<h2>Current training pools</h2>{table(training)}
<p>The current production union contains PINDER and pKPDB. The benchmark training split is shown separately because its frozen membership is not a claim that every example is in the current production run. The complex-only union excludes pKPDB monomers. Union counts deduplicate ATLAS IDs and sequence hashes; rows should not be added.</p>
<h2>Validation and held-out coverage</h2>{table(validation)}
<p>The current validation union contains 800 PINDER entries, 800 pKPDB entries (507 complexes and 293 monomers), and 142 active benchmark entries. There are <strong>604 ATLAS complexes with an exactly identical chain</strong> in that union, including <strong>14 with both exact partners within one validation entry</strong>. At ≥70% identity the corresponding counts are <strong>4,006</strong> and <strong>280</strong>. The full benchmark validation split contains 284 entries; the active 142 are a prepared subset.</p>
<p>Looking in the reverse direction, ATLAS represents at least one chain from <strong>175/800 PINDER validation entries (21.9%)</strong>, <strong>133/800 pKPDB validation entries (16.6%)</strong>, and <strong>24/142 active benchmark validation entries (16.9%)</strong> at the default threshold.</p>
<h2>How similarity changes with the threshold</h2>{threshold_table}
<p>All non-exact rows require ≥80% coverage of both sequences. Exact matching compares complete normalized sequences and is exhaustive, including short chains that a heuristic similarity search may miss. At ≥70% identity, {count(screen['no_detected_training_hit_70'])} complexes ({percent(screen['no_detected_training_hit_70'],N)}) have no detected chain match to the current PINDER/pKPDB training pools.</p>
<h2>Broader source collections and historical validation</h2>{table(scope)}
<p>Accepted-source rows include entries outside the current training pools. The pKPDB source-entity row uses canonical polymer entities, which do not preserve assembly copy multiplicity; a two-partner count is therefore omitted. Experimental-reference entries are individual sequences. The retired 400-entry PINDER validation set is retained for historical comparison.</p>
<h2>Adding ATLAS to jax-Ka</h2>
<ol><li><strong>Keep a versioned source dataset.</strong> The staging path is <code>$SCRATCH/_runtime/jax-Ka/pkabench/pretraining/atlas-high-confidence-v1</code>. It contains confidence metadata, unique sequences, PDB.gz tar shards, and archive receipts pinned to source revisions and checksums.</li>
<li><strong>Filter before preparation.</strong> The initial whole-chain screen flags {count(screen['preliminary_holdout_flag'])} complexes against validation/test at 70% or experimental reference sequences at 30%, always with 80% coverage of both chains. {count(screen['passes_preliminary_holdout_screen'])} pass that preliminary screen; {count(screen['passes_preliminary_screen_and_length'])} also meet the existing 1,500-residue pair limit. These counts still need the project’s antibody/CDR and one-sided fragment rules before they define a training cohort.</li>
{('<li><strong>Withhold the source-quality exception.</strong> Excluding ID_464531 leaves 163,759 candidates after the preliminary sequence and length checks. The remaining project-specific leakage checks still apply.</li>') if qc else ''}
<li><strong>Control redundancy.</strong> ATLAS contains {count(cohort['unique_unordered_sequence_pairs'])} unique unordered exact sequence pairs, with {count(cohort['redundant_sequence_pair_records'])} additional records sharing a pair. The current pools have exact two-partner matches for {count(screen['exact_training_pair'])} ATLAS complexes. Choose representative pairs or use cluster-aware sampling; sequence-pair equality alone does not establish the same interface geometry.</li>
<li><strong>Prepare a predicted-structure cohort.</strong> Apply the jax-Ka structural preparation and site eligibility rules; generate pKAI labels for AB, A and B; then build graph records and a separate training manifest. Preserve confidence values and predicted-source provenance. ATLAS confidence is a structural prediction score, not an experimental pKa label.</li>
<li><strong>Evaluate through the existing validation sets.</strong> Keep the source separate in sampling and reporting so its effect can be measured. No ATLAS examples have been added to the active training manifests by this audit.</li></ol>
<h2>Method and reproducibility</h2><ul>
<li>Official metadata: 1,140,264 rows. The published cutoffs <code>LIS ≥ 0.203 AND LIA ≥ 3432</code> reproduce exactly 181,671 complexes. Six rows lack confidence values and are excluded. Metadata SHA256: <code>08740c654b0be90ed0284ece0f50e6c506f6ba2725de8c882d394cd9c43b36d3</code>.</li>
{('<li>ModelScope supplied 181,283 high-confidence structures; 388 additional files were recovered from the authors’ <a href="https://www.biopredictnavigator.cn">companion site</a>. Every recovered file has the exact canonical chain sequences; 387/388 have mean CA pLDDT within 0.15 of the metadata, and the remaining file is explicitly flagged. LIS/LIA values come from the official CSV. ModelScope archives have publisher-provided SHA256 values; companion file hashes are locally calculated. The companion site’s expired TLS certificate required a scoped exception for these public downloads, recorded in the receipts.</li>' if progress.get('companion_structures',0) else '')}
<li>Reference sequences use canonical sequences, not just resolved coordinates: PINDER prefilter sequence hashes, selected pKPDB chains from <code>defects.json</code>, and frozen benchmark memberships. All reference memberships were resolved; no missing-sequence records were silently omitted.</li>
<li>MMseqs2 ran in both directions across {count(Q)} ATLAS and {count(data['reference_unique_chains'])} unique reference chains. Parameters: <code>--min-seq-id 0.3 -c 0.8 --cov-mode 0 --alignment-mode 3 -s 7.5 -e 0.001 --max-seqs 10000</code>. Hits were combined by sequence pair and augmented with exact sequence equality. Identity means identical aligned residues divided by alignment length.</li>
<li>Similarity searches are heuristic; “no detected hit” does not prove absence of distant homology. Higher identity cutoffs are applied to MMseqs2’s reported three-decimal <code>fident</code> values, so boundary assignments have that precision. Same-entry partner counts are computed at exact identity and the 70% threshold. Whole-chain results do not reproduce the antibody/CDR exceptions or short-fragment exclusion policy. Same-entry matches do not measure structural similarity.</li>
<li>The main download and sequence analysis ran on Isambard GPU allocations, one node per allocation. Companion recovery ran locally on the Mac and was transferred to scratch. Final verification ran in a single-node GPU job. Source archives are SHA256-checked before selected structures are retained.</li></ul>
<h2>Files and sources</h2><p><a href="atlas-overlap-summary.tsv">Full coverage table (TSV)</a> · <a href="atlas-screening.tsv">Per-complex preliminary flags (TSV)</a> · <a href="atlas-analysis-provenance.json">Input and output hashes</a> · <a href="atlas-overlap-summary.json">Machine-readable results</a></p>
{('<p><a href="atlas-download-verification.json">Download verification</a> · <a href="atlas-dataset.json">Dataset manifest and source-quality exclusions</a></p>') if progress['complete'] else ''}
<p><a href="https://www.nature.com/articles/s41467-026-70884-4">ATLAS paper</a> · <a href="https://www.modelscope.cn/collections/protein_complex_atlas-2ae5e7d4f4a343">Official ModelScope collection</a> · <a href="https://github.com/soedinglab/MMseqs2">MMseqs2</a>. The dataset collection specifies CC BY-NC 4.0.</p>
<footer>Audit runtime: <code>$SCRATCH/_runtime/jax-Ka/pkabench/audits/atlas-v1</code>. The full alignments, frozen memberships, scripts and screening flags are retained there. The downloadable coverage table contains every dataset at every reported threshold.</footer>
</main></body></html>'''
(O/'atlas-coverage-report.html').write_text(body)
for src,dst in [('overlap-summary.tsv','atlas-overlap-summary.tsv'),('overlap-summary.json','atlas-overlap-summary.json'),('atlas-screening.tsv','atlas-screening.tsv'),('analysis-provenance.json','atlas-analysis-provenance.json')]:shutil.copyfile(B/src,O/dst)
for src,dst in [('verification.json','atlas-download-verification.json'),('dataset.json','atlas-dataset.json')]:
 if (B/src).exists():shutil.copyfile(B/src,O/dst)
print(O/'atlas-coverage-report.html')
